{"path": "verify.mjs", "content": "import assert from 'node:assert/strict';
import { mergeConfig } from './config.mjs';

// public tests
assert.deepEqual(mergeConfig({ mode: 'safe', retries: 3 }, { mode: 'fast' }),
  { mode: 'fast', retries: 3 });
assert.deepEqual(mergeConfig({ network: { host: 'localhost', port: 80 } }, { network: { port: 443 } }),
  { network: { host: 'localhost', port: 443 } });
assert.deepEqual(mergeConfig({ enabled: true, retries: 3 }, { enabled: false, retries: 0 }),
  { enabled: false, retries: 0 });

// no mutation of defaults
const d = { a: 1, n: { x: 1 } };
const r = mergeConfig(d, { n: { y: 2 } });
assert.deepEqual(d, { a: 1, n: { x: 1 } });
assert.notEqual(r, d);
assert.notEqual(r.n, d.n);

// fresh nested objects, no retained references
const nested = { x: 1 };
const r2 = mergeConfig({ n: nested }, {});
assert.notEqual(r2.n, nested);
const r3 = mergeConfig({}, { n: nested });
assert.notEqual(r3.n, nested);

// repeated calls independent
const def = { n: { x: 1 } };
const a = mergeConfig(def, { n: { y: 2 } });
const b = mergeConfig(def, { n: { z: 3 } });
assert.deepEqual(a, { n: { x: 1, y: 2 } });
assert.deepEqual(b, { n: { x: 1, z: 3 } });

// false/0/null overrides
assert.deepEqual(mergeConfig({ a: 1, b: 2, c: 3 }, { a: false, b: 0, c: null }),
  { a: false, b: 0, c: null });

// nested replaced by primitive and vice versa
assert.deepEqual(mergeConfig({ n: { x: 1 } }, { n: 5 }), { n: 5 });
assert.deepEqual(mergeConfig({ n: 5 }, { n: { x: 1 } }), { n: { x: 1 } });

// TypeError cases
for (const bad of [null, undefined, [], 5, 'x', true]) {
  assert.throws(() => mergeConfig(bad, {}), TypeError);
  assert.throws(() => mergeConfig({}, bad), TypeError);
}
assert.throws(() => mergeConfig(), TypeError);

// inherited keys ignored
const proto = { inherited: 1 };
const withProto = Object.create(proto);
withProto.own = 2;
assert.deepEqual(mergeConfig(withProto, {}), { own: 2 });

// __proto__ and constructor as data keys from JSON.parse
const parsed = JSON.parse('{"__proto__": {"polluted": true}, "constructor": 7}');
const out = mergeConfig({}, parsed);
assert.equal(Object.getPrototypeOf(out), Object.prototype);
assert.equal(Object.prototype.polluted, undefined);
assert.deepEqual(Object.keys(out).sort(), ['__proto__', 'constructor']);
assert.deepEqual(out['__proto__'], { polluted: true });
assert.equal(out.constructor, 7);

// __proto__ nested merge
const parsed2 = JSON.parse('{"__proto__": {"a": 1}}');
const out2 = mergeConfig(parsed2, JSON.parse('{"__proto__": {"b": 2}}'));
assert.deepEqual(out2['__proto__'], { a: 1, b: 2 });
assert.equal(Object.getPrototypeOf(out2), Object.prototype);

// null-prototype plain object accepted
const np = Object.create(null);
np.k = 1;
assert.deepEqual(mergeConfig(np, {}), { k: 1 });

console.log('all checks passed');
"}

